<template>
  <div class="tpl-page">
    <!-- 상단 바: 에디터와 공통 헤더. 단, 파일 관리 버튼들은 숨김 -->
    <AppHeader :show-actions="false" />

    <div class="tpl-body">
      <!-- 좌측: 부서/팀 트리 -->
      <aside class="tpl-sidebar">
        <button
          class="tpl-team tpl-team--top"
          :class="{ 'is-active': selectedTeam === '' }"
          @click="selectedTeam = ''"
        >
          전체
        </button>

        <div v-for="dept in departments" :key="dept.name" class="tpl-dept">
          <button class="tpl-dept-head" @click="toggle(dept.name)">
            <span>{{ dept.name }}</span>
            <i class="pi text-xs text-gray-400" :class="isOpen(dept.name) ? 'pi-angle-down' : 'pi-angle-right'"></i>
          </button>
          <div v-show="isOpen(dept.name)" class="tpl-team-list">
            <button
              v-for="team in dept.teams"
              :key="team"
              class="tpl-team"
              :class="{ 'is-active': selectedTeam === team }"
              @click="selectedTeam = team"
            >
              {{ team }}
            </button>
          </div>
        </div>
      </aside>

      <!-- 우측: 제목 + 검색 + 카드 그리드 -->
      <main class="tpl-main">
        <h1 class="tpl-title">템플릿을 선택해주세요</h1>

        <div class="tpl-search">
          <i class="pi pi-search"></i>
          <InputText
            v-model="search"
            placeholder="전시명 / 템플릿명을 입력하세요"
            class="tpl-search-input"
            aria-label="템플릿 검색"
          />
        </div>

        <div class="tpl-grid">
          <!-- 빈 템플릿 -->
          <button v-if="selectedTeam === '' && !search.trim()" class="tpl-card" @click="startBlank">
            <div class="tpl-thumb tpl-thumb--blank">
              <i class="pi pi-image tpl-blank-icon"></i>
              <div class="tpl-blank-lines">
                <span></span><span></span><span></span>
              </div>
            </div>
            <div class="tpl-card-name">빈 템플릿</div>
          </button>

          <!-- 템플릿 카드 -->
          <button
            v-for="t in filteredTemplates"
            :key="t.id"
            class="tpl-card"
            @click="pickTemplate(t)"
          >
            <div class="tpl-thumb">
              <iframe
                v-if="srcdocs[t.id]"
                :srcdoc="srcdocs[t.id]"
                class="tpl-thumb-iframe"
                sandbox="allow-same-origin"
                scrolling="no"
                loading="lazy"
              ></iframe>
              <div v-else class="tpl-thumb-loading">
                <i class="pi pi-spin pi-spinner text-gray-300"></i>
              </div>
            </div>
            <div class="tpl-card-name">{{ t.name }}</div>
          </button>

          <!-- 결과 없음 -->
          <div v-if="filteredTemplates.length === 0 && !(selectedTeam === '' && !search.trim())" class="tpl-empty">
            해당 조건의 템플릿이 없습니다.
          </div>
        </div>
      </main>
    </div>

    <!-- 템플릿 적용 중 오버레이 -->
    <div v-if="applying" class="tpl-overlay">
      <i class="pi pi-spin pi-spinner text-2xl text-blue-500"></i>
      <span>템플릿을 불러오는 중…</span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, reactive, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useModuleStore } from '@/stores/moduleStore'
import { useEditorStore } from '@/stores/editorStore'
import AppHeader from '@/components/layout/AppHeader.vue'
import type { NewsletterTemplate } from '@/types'

const router = useRouter()
const moduleStore = useModuleStore()
const editorStore = useEditorStore()

// 좌측 부서/팀 트리. 필터는 template.team 값과 매칭한다.
const departments = [
  { name: '펫레저사업본부', teams: ['펫산업팀', '레저산업팀'] },
  { name: '문화콘텐츠사업본부', teams: ['라이프콘텐츠팀'] },
  { name: '신성장산업본부', teams: ['신성장전략팀'] },
  { name: '융합사업본부', teams: ['융합산업1팀'] },
]

const selectedTeam = ref<string>('') // '' = 전체
const search = ref('')

// 부서 접기/펼치기 (기본 펼침)
const openDepts = reactive<Record<string, boolean>>(
  Object.fromEntries(departments.map((d) => [d.name, true])),
)
const isOpen = (name: string) => openDepts[name] !== false
const toggle = (name: string) => {
  openDepts[name] = !isOpen(name)
}

const templates = ref<NewsletterTemplate[]>([])
const srcdocs = reactive<Record<string, string>>({})
const applying = ref(false)

const filteredTemplates = computed(() => {
  const q = search.value.trim().toLowerCase()
  return templates.value.filter((t) => {
    const teamOk = selectedTeam.value === '' || t.team === selectedTeam.value
    const searchOk = !q || t.name.toLowerCase().includes(q)
    return teamOk && searchOk
  })
})

// 썸네일 iframe 문서 만들기 (680px로 렌더 → CSS scale로 축소해 고정 박스에 맞춤)
const buildThumbDoc = (content: string): string =>
  `<!DOCTYPE html><html><head><meta charset="utf-8"><base target="_blank">` +
  `<style>html,body{margin:0;padding:0;background:#fff;overflow:hidden;}*{box-sizing:border-box;}</style>` +
  `</head><body><div style="width:680px;max-width:680px;margin:0;">${content}</div></body></html>`

onMounted(async () => {
  templates.value = await moduleStore.loadAvailableTemplates()
  // 각 템플릿을 실제 렌더해 썸네일 생성 (순차 — 과도한 동시 fetch 방지)
  for (const t of templates.value) {
    try {
      const html = await moduleStore.renderTemplateHtml(t)
      srcdocs[t.id] = buildThumbDoc(html)
    } catch (e) {
      console.warn('[TemplateSelect] 썸네일 렌더 실패:', t.id, e)
    }
  }
})

// 빈 템플릿으로 시작 (에디터를 빈 상태로)
const startBlank = () => {
  moduleStore.clearAll()
  editorStore.setCurrentTemplateName('빈 템플릿')
  router.push('/editor')
}

// 템플릿 선택 → 적용 후 에디터로
const pickTemplate = async (t: NewsletterTemplate) => {
  if (applying.value) return
  applying.value = true
  try {
    await moduleStore.loadTemplate(t.id)
    editorStore.setCurrentTemplateName(t.name)
    router.push('/editor')
  } finally {
    applying.value = false
  }
}
</script>

